// Fetches every page of /orders per ../backend/contract.json:
// request  { page }          integer starting at 1
// response { items, next_page } items is an array; next_page is an integer or null
// Returns a flat array of all items across all pages.
export async function fetchAll(fetchPage) {
  const items = [];
  let page = 1;
  do {
    const data = await fetchPage({ page });
    items.push(...data.items);
    page = data.next_page;
  } while (page != null);
  return items;
}
